         if path.is_dir():","                    if not recursive: raise NuError(\"cannot remove directory without --recursive\")","                    shutil.rmtree(path)","                elif path.exists(): path.unlink()","            return None","        if name in (\"cp\", \"mv\"):","            source, target = args[-2:]","            (shutil.copy2 if name == \"cp\" else shutil.move)(source, target)","            return None","        if name == \"save\":","            path = Path(args[-1])","            append = any(t.value in (\"-a\", \"--append\") for t in tokens)","            mode = \"ab\" if append else \"wb\"","            content = value if isinstance(value, bytes) else display_scalar(value).encode(\"utf-8\")","            with path.open(mode) as handle: handle.write(content)","            return None","        if name == \"open\":","            raw = any(t.value in (\"-r\", \"--raw\") for t in tokens)","            path = Path(args[-1])","            data = path.read_text(encoding=\"utf-8-sig\")","            if raw: return data","            if path.suffix.lower() == \".json\": return json.loads(data)","            if path.suffix.lower() in (\".csv\", \".tsv\"):","                fmt = \"tsv\" if path.suffix.lower() == \".tsv\" else \"csv\"","                return self.from_command([Token(\"word\", fmt, 0)], data, env)","            return data","        if name == \"glob\":","            import glob as glob_module","            return glob_module.glob(args[0], recursive=True)","        if name == \"ls\":","            pattern = args[0] if args else \"*\"","            base = Path(pattern).parent if Path(pattern).parent != Path(\"\") else Path(\".\")","            mask = Path(pattern).name","            entries = [p for p in base.iterdir() if fnmatch.fnmatch(p.name, mask)]","            rows = []","            for path in sorted(entries, key=lambda p: p.name.casefold()):","                stat = path.stat()","                rows.append({\"name\": 